export const accountRoutes=['/compte','/compte/historique','/compte/collection','/compte/classement'];
const escape=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const tabs=[['/compte/','Vue d’ensemble'],['/compte/classement/','Rang & ELO'],['/compte/collection/','Collection'],['/compte/historique/','Historique']];
export function accountPage(){return `<section class="screen account-screen" aria-labelledby="screen-title"><div class="account-heading"><p class="eyebrow">ESPACE JOUEUR / VOTRE TRAJECTOIRE</p><h1 id="screen-title" tabindex="-1">Votre place dans ORA.</h1></div><nav class="account-tabs" aria-label="Espace joueur">${tabs.map(([url,title])=>`<a href="${url}" ${location.pathname.replace(/\/$/,'')===url.replace(/\/$/,'')?'aria-current="page"':''}>${title}</a>`).join('')}</nav><div id="account-content" aria-live="polite"><p class="account-loading">Chargement de votre profil…</p></div></section>`;}
async function api(path,body){const r=await fetch('/account-api/'+path,{credentials:'same-origin',headers:body?{'content-type':'application/json'}:{},...(body?{method:'POST',body:JSON.stringify(body)}:{})});if(!r.ok)throw new Error(r.status===401?'Votre session a expiré. Reconnectez-vous.':'Le service est momentanément indisponible. Réessayez dans un instant.');return r.json();}
const fmt=n=>n===null||n===undefined?'—':new Intl.NumberFormat('fr-FR').format(n);
function metrics(d){return `<div class="player-metrics">${[['Niveau',d.profile.level,'Progression du compte'],['Expérience',d.profile.experience,'XP enregistrée'],['ELO',d.competitive?.elo,'Classement compétitif'],['Points',d.wallet?.points,'Solde du compte']].map(([name,value,caption])=>`<article><span class="eyebrow">${name}</span><strong>${fmt(value)}</strong><p>${value===null||value===undefined?'Pas encore disponible':caption}</p></article>`).join('')}</div>`;}
function signedOut(){return `<div class="account-welcome"><div><p class="eyebrow">UNE IDENTITÉ / UN PARCOURS</p><h2>Retrouvez votre profil.</h2><p>Connectez-vous pour consulter votre progression, vos résultats et votre collection ORA.</p><button id="steam-login" class="account-primary">Se connecter avec Steam ↗</button><p class="note">La connexion s’effectue sur Steam. ORA ne reçoit jamais votre mot de passe Steam. La session du site dure au maximum 7 jours.</p><p class="note">La liaison avec un ancien compte invité du jeu reste à intégrer.</p><p id="login-feedback" role="status"></p></div><div class="account-emblem" aria-hidden="true">◇<small>ORA / JOUEUR</small></div></div><div class="account-preview"><span>PROGRESSION</span><span>RANG & ELO</span><span>COLLECTION</span><span>HISTORIQUE</span></div><p class="content-state">Le classement, les points et les skins apparaîtront lorsqu’ils seront attribués par le jeu. Aucun résultat de démonstration n’est ajouté à votre compte.</p>`;}
function empty(title,text){return `<div class="account-empty"><span aria-hidden="true">◇</span><h2>${title}</h2><p>${text}</p><a href="/jeu/" class="text-action">EXPLORER LE JEU ↗</a></div>`;}
function history(d){return `<h2>Vos derniers matchs.</h2><p class="note">Résultats terminés associés à votre compte par le serveur de jeu.</p>${d.matches.length?`<div class="match-list">${d.matches.map(m=>`<article><span class="match-result ${m.winning_team===m.team?'win':'loss'}">${m.winning_team===m.team?'Victoire':'Défaite'}</span><div><h3>${escape(m.map_name)}</h3><p>${escape(new Date(m.ended_at).toLocaleString('fr-FR'))}</p></div><strong>${m.score_team_a} — ${m.score_team_b}</strong><span>${m.goals} buts · ${m.eliminations} éliminations</span></article>`).join('')}</div>${d.hasMore?'<button id="more-matches" class="account-secondary">Voir les matchs précédents</button>':''}`:empty('Votre histoire commence ici.','Aucun match terminé n’est encore rattaché à ce compte. Les parties apparaîtront dès que le serveur aura transmis votre participation et leur résultat.')}`;}
export async function wireAccount(){const target=document.querySelector('#account-content');if(!target)return;try{const session=await api('session');if(!target.isConnected)return;if(!session.authenticated){target.innerHTML=signedOut();const reason=new URLSearchParams(location.search).get('connexion');if(reason==='echec')document.querySelector('#login-feedback').textContent='La connexion n’a pas abouti. Vous pouvez réessayer.';document.querySelector('#steam-login').onclick=async e=>{e.target.disabled=true;try{const data=await api('auth/steam',{});const url=new URL(data.url);if(url.origin!=='https://steamcommunity.com')throw new Error('Adresse de connexion invalide.');location.assign(url.href);}catch(error){document.querySelector('#login-feedback').textContent=error.message;e.target.disabled=false;}};return;}
const data=await api('dashboard');if(!target.isConnected)return;const path=location.pathname.replace(/\/$/,'');const header=`<div class="player-identity"><div><span class="eyebrow">COMPTE CONNECTÉ</span><h2>${escape(data.profile.display_name)}</h2><p>${session.steamId?'Steam · '+escape(session.steamId):'Compte ORA'}</p></div><button id="logout" class="account-secondary">Se déconnecter</button></div>`;
let body='';if(path==='/compte/historique'){const result=await api('matches');body=history(result);}else if(path==='/compte/collection'){body=`<h2>Votre collection.</h2><p class="note">Les apparences attribuées à votre compte ORA.</p>${data.inventory.length?'<div class="skin-grid">'+data.inventory.map(s=>`<article><span aria-hidden="true">◇</span><h3>${escape(s.name)}</h3><p>${escape(s.character_key)}</p><small>${escape(s.rarity||'Apparence')}</small></article>`).join('')+'</div>':empty('Une collection à construire.','Aucune apparence n’est encore attribuée à votre compte. Le catalogue de skins et leurs conditions d’obtention sont en préparation.')}`;}else if(path==='/compte/classement'){body=`<div class="rank-panel"><div class="rank-emblem" aria-hidden="true">◇</div><div><p class="eyebrow">VOTRE RANG</p><h2>${escape(data.competitive?.rank||'Non classé')}</h2><p class="elo-value">${fmt(data.competitive?.elo)} <span>ELO</span></p><p>${data.competitive?'Dernière mesure enregistrée pour votre compte.':'Votre rang et votre ELO seront affichés dès que le système compétitif les aura attribués.'}</p><p class="content-state">Les saisons et le barème de classement restent à définir.</p></div></div>`;}else{body=metrics(data)+`<div class="account-summary"><article><h2>Votre progression.</h2><p>${data.summary.played} matchs terminés · ${data.summary.wins} victoires enregistrées</p><a class="text-action" href="/compte/historique/">CONSULTER L’HISTORIQUE ↗</a></article><article><h2>Vos apparences.</h2><p>${data.inventory.length} apparence${data.inventory.length>1?'s':''} attribuée${data.inventory.length>1?'s':''}</p><a class="text-action" href="/compte/collection/">OUVRIR LA COLLECTION ↗</a></article></div><p class="content-state">Les données affichées proviennent du compte ORA. Une valeur « — » signifie que le système correspondant n’a pas encore attribué de donnée.</p>`;}
if(!target.isConnected)return;target.innerHTML=header+body;document.querySelector('#logout').onclick=async e=>{e.target.disabled=true;try{await api('logout',{});wireAccount();}catch(error){e.target.disabled=false;e.target.textContent='Réessayer la déconnexion';}};const more=document.querySelector('#more-matches');if(more){let offset=20;more.onclick=async()=>{more.disabled=true;try{const next=await api('matches?offset='+offset);const box=document.createElement('div');box.innerHTML=history(next);document.querySelector('.match-list').insertAdjacentHTML('beforeend',box.querySelector('.match-list')?.innerHTML||'');offset+=20;more.hidden=!next.hasMore;}catch(error){more.textContent='Réessayer le chargement';}finally{more.disabled=false;}};}
}catch(error){if(target.isConnected){target.innerHTML=`<div class="account-empty"><h2>Connexion indisponible.</h2><p>${escape(error.message)}</p><button id="retry-account" class="account-primary">Réessayer</button></div>`;document.querySelector('#retry-account').onclick=wireAccount;}}}
